#!/usr/bin/env python3
"""Collect copyright evidence for Debian packages that own bundled AppDir files."""

from __future__ import annotations

import argparse
import gzip
import hashlib
import json
import os
import re
import subprocess
import sys
from collections.abc import Callable
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
from license_expression import load_catalog, normalize_expression

# ca-certificates.crt is generated by ca-certificates.postinst and therefore
# is not necessarily present in the package's dpkg .list file.
GENERATED_FILE_OWNERS = {
    "/etc/ssl/certs/ca-certificates.crt": "ca-certificates",
}

# Ubuntu 24.04's base-files package does not ship this Debian common license.
# Pin the exact Debian common-licenses text so native copyright references remain
# resolvable without substituting the materially different GFDL 1.3 text.
BUNDLED_COMMON_LICENSES_DIR = (
    Path(__file__).resolve().parent / "licenses" / "common-licenses"
)
BUNDLED_COMMON_LICENSE_SHA256 = {
    "GFDL-1.2": "2652c22ba086f92e55ae4a9f9c890ad4766ffd7814a73d318e22a597edf857a4",
}


def query_package_metadata(package: str) -> dict[str, str | None]:
    result = subprocess.run(
        [
            "dpkg-query", "-W",
            "-f=${Version}\\t${source:Package}\\t${source:Version}",
            package,
        ],
        check=False,
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise ValueError(
            f"cannot query installed package metadata for {package}: {result.stderr.strip()}"
        )
    fields = result.stdout.rstrip("\n").split("\t")
    if len(fields) != 3 or not fields[0].strip():
        raise ValueError(f"dpkg-query returned incomplete metadata for {package}")
    return {
        "version": fields[0].strip(),
        "source_package": fields[1].strip() or package.split(":", 1)[0],
        "source_version": fields[2].strip() or fields[0].strip(),
    }


def _package_file_owners(dpkg_info_dir: Path) -> dict[str, set[str]]:
    owners: dict[str, set[str]] = {}
    for list_file in sorted(dpkg_info_dir.glob("*.list")):
        package = list_file.name[:-5]
        for raw_path in list_file.read_text(encoding="utf-8", errors="replace").splitlines():
            if raw_path.startswith("/"):
                owners.setdefault(raw_path, set()).add(package)
    return owners


def _copyright_document(
    doc_root: Path, package: str, source_package: str
) -> tuple[bytes | None, str | None]:
    candidates = []
    for name in dict.fromkeys((package.split(":", 1)[0], source_package)):
        candidates.extend((doc_root / name / "copyright", doc_root / name / "copyright.gz"))
    for candidate in candidates:
        if not candidate.is_file():
            continue
        try:
            if candidate.suffix == ".gz":
                with gzip.open(candidate, "rb") as handle:
                    return handle.read(), str(candidate)
            return candidate.read_bytes(), str(candidate)
        except (OSError, EOFError) as exc:
            raise ValueError(f"cannot read copyright evidence {candidate}: {exc}") from exc
    return None, None


def _safe_name(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9.+_-]+", "_", value)


def _stage_referenced_common_licenses(
    content: bytes,
    common_licenses_dir: Path,
    output_dir: Path,
) -> list[dict[str, str]]:
    text = content.decode("utf-8", errors="replace")
    names = sorted({
        match.rstrip(".")
        for match in re.findall(
            r"(?:/usr/share/)?common-licenses/([A-Za-z0-9.+_-]+)",
            text,
        )
    })
    evidence: list[dict[str, str]] = []
    for name in names:
        source = common_licenses_dir / name
        bundled_source = BUNDLED_COMMON_LICENSES_DIR / name
        if name in BUNDLED_COMMON_LICENSE_SHA256 and bundled_source.is_file():
            source = bundled_source
            license_content = source.read_bytes()
            actual_sha256 = hashlib.sha256(license_content).hexdigest()
            expected_sha256 = BUNDLED_COMMON_LICENSE_SHA256[name]
            if actual_sha256 != expected_sha256:
                raise ValueError(
                    f"bundled common license integrity failure for {name}: "
                    f"expected {expected_sha256}, got {actual_sha256}"
                )
        elif source.is_file():
            license_content = source.read_bytes()
        else:
            raise ValueError(
                f"copyright document references missing common license text: {source}"
            )
        relative = f"third-party/native/common-licenses/{name}"
        destination = output_dir / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        if destination.exists() and destination.read_bytes() != license_content:
            raise ValueError(
                f"refusing to overwrite different common license evidence: {destination}"
            )
        destination.write_bytes(license_content)
        evidence.append({
            "name": name,
            "source_path": str(source),
            "artifact_path": relative,
            "sha256": hashlib.sha256(license_content).hexdigest(),
        })
    return evidence


def _dep5_paragraphs(content: bytes) -> list[dict[str, str]]:
    """Parse DEP-5 paragraphs while keeping continuation lines with their field."""
    text = content.decode("utf-8", errors="replace")
    paragraphs: list[dict[str, str]] = []
    current: dict[str, str] = {}
    for line in text.splitlines() + [""]:
        if not line.strip():
            if current:
                paragraphs.append(current)
                current = {}
            continue
        if line[:1].isspace() and current:
            key = next(reversed(current))
            current[key] += "\n" + line.strip()
            continue
        if ":" in line:
            key, value = line.split(":", 1)
            current[key.strip()] = value.strip()
    return paragraphs


def _normalize_debian_license_value(expression: str) -> str | None:
    aliases = {
        "gpl-2+": "GPL-2.0-or-later",
        "gpl-2": "GPL-2.0-only",
        "gpl-3+": "GPL-3.0-or-later",
        "gpl-3": "GPL-3.0-only",
        "lgpl-2.1+": "LGPL-2.1-or-later",
        "lgpl-2.1": "LGPL-2.1-only",
        "lgpl-3+": "LGPL-3.0-or-later",
        "lgpl-3": "LGPL-3.0-only",
        "bsd-3-clause": "BSD-3-Clause",
        "bsd-2-clause": "BSD-2-Clause",
        "apache-2": "Apache-2.0",
        "apache-2.0": "Apache-2.0",
        "expat": "MIT",
        "zlib": "Zlib",
        "psf-2": "PSF-2.0",
        "cc-by-sa-3.0-us": "CC-BY-SA-3.0-US",
        "cc-by-sa-3.0": "CC-BY-SA-3.0",
        "mpl-1.1": "MPL-1.1",
        "mpl-2.0": "MPL-2.0",
        "mit": "MIT",
        "isc": "ISC",
        "cc0-1.0": "CC0-1.0",
    }
    value = expression.casefold()
    for debian_name, spdx_name in aliases.items():
        pattern = rf"(?<![a-z0-9.+-]){re.escape(debian_name)}(?![a-z0-9.+-])"
        value = re.sub(pattern, spdx_name, value)
    value = re.sub(r"(?<![A-Za-z0-9.+-])or(?![A-Za-z0-9.+-])", "OR", value, flags=re.IGNORECASE)
    value = re.sub(
        r"(?<![A-Za-z0-9.+-])and(?![A-Za-z0-9.+-])",
        "AND",
        value,
        flags=re.IGNORECASE,
    )
    value = re.sub(r"\s+", " ", value).strip()
    if not value or re.search(r"[^A-Za-z0-9.+() -]", value):
        return None
    tokens = value.replace("(", " ( ").replace(")", " ) ").split()
    if any(
        token not in {"AND", "OR", "WITH", "(", ")"}
        and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9.+-]*", token)
        for token in tokens
    ):
        return None
    try:
        licenses, exceptions = load_catalog(
            Path(__file__).resolve().parent / "licenses" / "spdx-3.29.0-licenses.json",
            Path(__file__).resolve().parent / "licenses" / "spdx-3.29.0-exceptions.json",
        )
        return normalize_expression(value, licenses, exceptions)
    except (OSError, ValueError):
        return None


def _debian_license_expression(content: bytes) -> tuple[str, str]:
    """Resolve only an explicit DEP-5 package declaration or a safe catch-all."""
    paragraphs = _dep5_paragraphs(content)
    if not paragraphs:
        return "NOASSERTION", "unknown"

    header = paragraphs[0]
    format_value = header.get("Format", "").rstrip("/")
    if not format_value.endswith("/copyright-format/1.0"):
        return "NOASSERTION", "unknown"

    # DEP-5 header License describes the package as a whole. Stand-alone
    # License paragraphs only supply referenced license text and are ignored.
    header_license = header.get("License", "").splitlines()[0].strip()
    if header_license:
        normalized = _normalize_debian_license_value(header_license)
        return (normalized, "verified") if normalized else ("NOASSERTION", "unknown")

    file_paragraphs = [
        paragraph for paragraph in paragraphs
        if "Files" in paragraph and paragraph.get("License", "").strip()
    ]
    if not file_paragraphs:
        return "NOASSERTION", "unknown"

    # Without a package-level declaration, require an explicit Files: * default
    # and identical normalized declarations across every Files stanza. This
    # deliberately rejects partial coverage and mixed-license packages.
    has_catch_all = any(
        "*" in paragraph["Files"].split()
        for paragraph in file_paragraphs
    )
    if not has_catch_all:
        return "NOASSERTION", "unknown"

    normalized = []
    for paragraph in file_paragraphs:
        declaration = paragraph["License"].splitlines()[0].strip()
        value = _normalize_debian_license_value(declaration)
        if value is None:
            return "NOASSERTION", "unknown"
        normalized.append(value)
    if len(set(normalized)) != 1:
        return "NOASSERTION", "unknown"
    return normalized[0], "verified"

def _debian_license_evidence(
    content: bytes, copyright_artifact_path: str
) -> list[dict[str, Any]]:
    """Preserve DEP-5 file-level license declarations without package aggregation."""
    text = content.decode("utf-8", errors="replace")
    paragraphs = _dep5_paragraphs(content)
    if not paragraphs or not paragraphs[0].get("Format", "").rstrip("/").endswith(
        "/copyright-format/1.0"
    ):
        return []
    evidence: list[dict[str, Any]] = []
    current: dict[str, str] = {}

    def flush() -> None:
        # Header and stand-alone License paragraphs are not file-level evidence.
        if "Files" not in current:
            return
        license_value = current.get("License", "").strip()
        if not license_value:
            return
        license_lines = license_value.splitlines()
        declaration = license_lines[0].strip()
        license_text = "\n".join(license_lines[1:]).strip()
        file_patterns = [
            pattern
            for line in current.get("Files", "").splitlines()
            for pattern in line.split()
        ]
        item: dict[str, Any] = {
            "file_patterns": file_patterns,
            "license_declaration": declaration,
            "license_text_kind": (
                "embedded" if license_text else "reference-or-not-provided"
            ),
            "copyright_artifact_path": copyright_artifact_path,
        }
        if license_text:
            item["license_text_sha256"] = hashlib.sha256(
                license_text.encode("utf-8")
            ).hexdigest()
        evidence.append(item)

    for line in text.splitlines() + [""]:
        if not line.strip():
            flush()
            current = {}
            continue
        if line[:1].isspace() and current:
            key = next(reversed(current))
            current[key] += "\n" + line.strip()
            continue
        if ":" in line:
            key, value = line.split(":", 1)
            current[key.strip()] = value.strip()
    return evidence


def _libmpdec_evidence(content: bytes) -> tuple[bool, str, str]:
    text = content.decode("utf-8", errors="replace")
    matching_stanzas = []
    for stanza in re.split(r"\n\s*\n", text):
        lowered = stanza.casefold()
        if "stefan krah" in lowered and ("libmpdec" in lowered or "_decimal" in lowered):
            matching_stanzas.append(stanza.encode("utf-8"))
    if not matching_stanzas:
        return False, "NOASSERTION", "unknown"
    expression, status = _debian_license_expression(b"\n\n".join(matching_stanzas))
    return True, expression, status


def collect_package_provenance(
    appdir: Path,
    dpkg_info_dir: Path,
    doc_root: Path,
    output_dir: Path,
    package_metadata_resolver: Callable[[str], dict[str, str | None]] = query_package_metadata,
    architecture: str = "unknown",
    common_licenses_dir: Path = Path("/usr/share/common-licenses"),
) -> dict[str, Any]:
    """Map AppDir files to installed Debian packages and stage their copyright.

    Every package mapped to a bundled file must have a readable copyright file.
    Missing documents are reported and cause a fail-closed ValueError.
    """
    if not appdir.is_dir():
        raise ValueError(f"AppDir does not exist: {appdir}")
    if not dpkg_info_dir.is_dir():
        raise ValueError(f"dpkg info directory does not exist: {dpkg_info_dir}")
    if not doc_root.is_dir():
        raise ValueError(f"package documentation directory does not exist: {doc_root}")

    owners_by_path = _package_file_owners(dpkg_info_dir)
    owners_by_library_filename: dict[str, dict[str, set[str]]] = {}
    for source_path, packages in owners_by_path.items():
        filename = Path(source_path).name
        is_system_multiarch_library = re.fullmatch(
            r"/(?:lib|usr/lib)/[^/]+/lib[^/]+\.so\.\d+(?:\.\d+)*",
            source_path,
        )
        if is_system_multiarch_library and re.fullmatch(
            r"lib[^/]+\.so\.\d+(?:\.\d+)*", filename
        ):
            for package in packages:
                owners_by_library_filename.setdefault(filename, {}).setdefault(
                    package, set()
                ).add(source_path)

    package_paths: dict[str, list[str]] = {}
    package_source_paths: dict[str, set[str]] = {}
    package_detection_methods: dict[str, set[str]] = {}
    for appdir_path in sorted(appdir.rglob("*")):
        if appdir_path.is_dir():
            continue
        try:
            relative = appdir_path.relative_to(appdir)
        except ValueError:
            continue
        host_paths = {"/" + relative.as_posix()}
        if appdir_path.is_symlink():
            link_target = Path(os.readlink(appdir_path))
            if link_target.is_absolute():
                target_relative = Path(str(link_target).lstrip("/"))
            else:
                target_relative = Path(os.path.normpath(str(relative.parent / link_target)))
            if target_relative != Path("..") and not str(target_relative).startswith("../"):
                host_paths.add("/" + target_relative.as_posix())
        matched = False
        for host_path in host_paths:
            for package in owners_by_path.get(host_path, set()):
                package_paths.setdefault(package, []).append(relative.as_posix())
                package_source_paths.setdefault(package, set()).add(host_path)
                package_detection_methods.setdefault(package, set()).add(
                    "dpkg-file-list" if host_path == "/" + relative.as_posix()
                    else "dpkg-file-list-symlink-target"
                )
                matched = True

        # linuxdeploy may flatten a multiarch library into AppDir/usr/lib and
        # copy its SONAME file as a regular ELF file. In that case the copied
        # basename (e.g. libfoo.so.2) differs from the dpkg-listed real file
        # (e.g. libfoo.so.2.0.0). Attribute it only when that SONAME filename
        # maps to exactly one installed package.
        if (
            not matched
            and relative.parts[:2] == ("usr", "lib")
            and re.fullmatch(r"lib[^/]+\.so\.\d+(?:\.\d+)*", relative.name)
            and appdir_path.is_file()
        ):
            with appdir_path.open("rb") as handle:
                is_elf = handle.read(4) == b"\x7fELF"
            if is_elf:
                candidates = {
                    filename: package_map
                    for filename, package_map in owners_by_library_filename.items()
                    if filename == relative.name or filename.startswith(relative.name + ".")
                }
                candidate_packages = {
                    package for package_map in candidates.values() for package in package_map
                }
                if len(candidate_packages) > 1:
                    raise ValueError(
                        "ambiguous dpkg ownership for flattened AppDir library "
                        + relative.as_posix()
                        + ": "
                        + ", ".join(sorted(candidate_packages))
                    )
                if len(candidate_packages) == 1:
                    package = next(iter(candidate_packages))
                    source_paths = {
                        source_path
                        for package_map in candidates.values()
                        for source_path in package_map.get(package, set())
                    }
                    package_paths.setdefault(package, []).append(relative.as_posix())
                    package_source_paths.setdefault(package, set()).update(source_paths)
                    package_detection_methods.setdefault(package, set()).add(
                        "dpkg-file-list-unique-soname-filename"
                    )

    generated_paths_by_package: dict[str, list[str]] = {}
    for host_path, package in GENERATED_FILE_OWNERS.items():
        generated_path = appdir / host_path.lstrip("/")
        if generated_path.is_file():
            if package in owners_by_path.get(host_path, set()):
                # A dpkg-listed file already has direct package provenance;
                # require postinst evidence only for an unlisted generated output.
                continue
            package_paths.setdefault(package, []).append(host_path.lstrip("/"))
            generated_paths_by_package.setdefault(package, []).append(host_path)

    output_dir.mkdir(parents=True, exist_ok=True)
    records: list[dict[str, Any]] = []
    missing: list[str] = []
    package_evidence: dict[str, str] = {}
    package_copyright: dict[str, bytes] = {}
    for package in sorted(package_paths):
        metadata = package_metadata_resolver(package)
        version = metadata.get("version")
        source_package = metadata.get("source_package") or package.split(":", 1)[0]
        if not isinstance(version, str) or not version.strip():
            raise ValueError(f"installed package version is unknown for {package}")
        content, source_document = _copyright_document(doc_root, package, source_package)
        package_directory = _safe_name(package.split(":", 1)[0])
        destination_relative = f"third-party/native/{package_directory}/copyright"
        destination = output_dir / destination_relative
        copyright_status = "present" if content is not None else "missing"
        license_expression, license_status = (
            _debian_license_expression(content)
            if content is not None
            else ("NOASSERTION", "unknown")
        )
        license_evidence = (
            _debian_license_evidence(content, destination_relative)
            if content is not None else []
        )
        if license_status == "verified":
            license_resolution_reason = (
                "All parsed copyright license declarations resolve to one canonical "
                "SPDX expression."
            )
        elif content is None:
            license_resolution_reason = "No readable package copyright document was available."
        else:
            license_resolution_reason = (
                "The copyright document is preserved, but its file-level declarations "
                "are multiple, custom, non-SPDX, or otherwise ambiguous; no package-level "
                "license expression is inferred."
            )
        referenced_common_licenses: list[dict[str, str]] = []
        if content is not None:
            destination.parent.mkdir(parents=True, exist_ok=True)
            if destination.exists() and destination.read_bytes() != content:
                raise ValueError(
                    f"refusing to overwrite different copyright evidence: {destination}"
                )
            destination.write_bytes(content)
            package_evidence[package] = destination_relative
            package_copyright[package] = content
            referenced_common_licenses = _stage_referenced_common_licenses(
                content, common_licenses_dir, output_dir
            )
        else:
            missing.append(package)
        package_list = dpkg_info_dir / f"{package}.list"
        source_paths = (
            [f"/var/lib/dpkg/info/{package}.list"] if package_list.is_file() else []
        )
        source_paths.extend(sorted(package_source_paths.get(package, set())))
        source_paths.extend(
            item["source_path"] for item in referenced_common_licenses
        )
        generated_paths = generated_paths_by_package.get(package, [])
        generated_output_provenance: list[dict[str, str]] = []
        if generated_paths:
            marker_relative = "ca-certificates-generation.sha256"
            marker_path = output_dir / marker_relative
            if not marker_path.is_file():
                raise ValueError(
                    f"generated AppDir output for {package} has no build generation evidence"
                )
            recorded_sha256 = marker_path.read_text(encoding="utf-8").strip()
            for generated_path in generated_paths:
                artifact_path = appdir / generated_path.lstrip("/")
                if not artifact_path.is_file():
                    raise ValueError(
                        f"generated AppDir output is missing: {generated_path}"
                    )
                actual_sha256 = hashlib.sha256(artifact_path.read_bytes()).hexdigest()
                if recorded_sha256 != actual_sha256:
                    raise ValueError(
                        f"generated AppDir output hash does not match build evidence: "
                        f"{generated_path}"
                    )
                generated_output_provenance.append({
                    "artifact_path": generated_path.lstrip("/"),
                    "generation_command": "sudo update-ca-certificates --fresh",
                    "generation_script": "packaging/appimage/bundle-runtime.sh",
                    "generation_marker": (
                        "usr/share/licenses/ClamGuardian/" + marker_relative
                    ),
                    "generated_sha256": actual_sha256,
                    "generation_exit_status": "0",
                })
            source_paths.extend([
                "packaging/appimage/bundle-runtime.sh",
                "usr/share/licenses/ClamGuardian/" + marker_relative,
            ])
            package_detection_methods.setdefault(package, set()).add(
                "known-generated-build-command-output"
            )
        if package_list.is_file() and not package_detection_methods.get(package):
            package_detection_methods.setdefault(package, set()).add("dpkg-file-list")
        detection_method = "+".join(sorted(package_detection_methods.get(package, set())))
        records.append({
            "package": package,
            "version": version,
            "source_package": source_package,
            "source_version": metadata.get("source_version") or version,
            "architecture": architecture,
            "artifact_paths": sorted(set(package_paths[package])),
            "source_paths": source_paths,
            "referenced_common_licenses": referenced_common_licenses,
            "generated_output_provenance": generated_output_provenance,
            "detection_method": detection_method,
            "copyright_status": copyright_status,
            "copyright_source": source_document,
            "copyright_artifact_path": destination_relative if content is not None else None,
            "license": license_expression,
            "license_status": license_status,
            "license_resolution_reason": license_resolution_reason,
            "license_evidence": license_evidence,
        })

    embedded_components: list[dict[str, Any]] = []
    missing_embedded_evidence: list[str] = []
    for package, paths in package_paths.items():
        decimal_paths = [
            path for path in paths
            if Path(path).name.startswith("_decimal") and Path(path).suffix == ".so"
        ]
        if not decimal_paths:
            continue
        evidence_path = package_evidence.get(package)
        content = package_copyright.get(package)
        if evidence_path is None or content is None:
            missing_embedded_evidence.append(package)
            continue
        has_notice, embedded_license, embedded_license_status = _libmpdec_evidence(content)
        if not has_notice:
            missing_embedded_evidence.append(package)
            continue
        embedded_components.append({
            "id": "embedded-libmpdec",
            "name": "libmpdec",
            "version": None,
            "version_status": "unknown",
            "architecture": architecture,
            "license": embedded_license,
            "license_status": embedded_license_status,
            "source": (
                "Embedded in the bundled Ubuntu Python 3.12 _decimal extension; package "
                "copyright stanza identifies Stefan Krah and the _decimal/libmpdec source"
            ),
            "source_package": package.split(":", 1)[0],
            "artifact_paths": sorted(decimal_paths),
            "source_paths": [f"/var/lib/dpkg/info/{package}.list"],
            "evidence_paths": [evidence_path],
            "detection_method": "dpkg-file-list-and-python-extension-path",
            "verification_status": "partial",
        })
        break

    manifest = {
        "schema_version": 1,
        "architecture": architecture,
        "detection_method": "dpkg-file-list-to-AppDir-path-mapping",
        "packages": records,
        "embedded_components": embedded_components,
        "missing_copyright_packages": missing,
        "missing_embedded_component_evidence": missing_embedded_evidence,
    }
    manifest_path = output_dir / "native-packages.json"
    manifest_path.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    if missing:
        raise ValueError("missing package copyright documents for: " + ", ".join(missing))
    if missing_embedded_evidence:
        raise ValueError(
            "missing libmpdec copyright/license evidence for: "
            + ", ".join(missing_embedded_evidence)
        )
    return manifest


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--appdir", type=Path, required=True)
    parser.add_argument("--dpkg-info-dir", type=Path, default=Path("/var/lib/dpkg/info"))
    parser.add_argument("--doc-root", type=Path, default=Path("/usr/share/doc"))
    parser.add_argument(
        "--common-licenses-dir", type=Path, default=Path("/usr/share/common-licenses")
    )
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--architecture", required=True, choices=("x86_64", "aarch64"))
    args = parser.parse_args(argv)
    try:
        result = collect_package_provenance(
            args.appdir, args.dpkg_info_dir, args.doc_root, args.output_dir,
            architecture=args.architecture,
            common_licenses_dir=args.common_licenses_dir,
        )
    except (OSError, ValueError) as exc:
        print(f"native license collection failed: {exc}", file=sys.stderr)
        return 1
    print(f"Collected copyright evidence for {len(result['packages'])} bundled Debian packages")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
